-- One-time published-baseline rerun for arena-2026-09-18.
-- Installing this migration changes no competition row. The private prepare
-- RPC performs one atomic archive/reopen after every sealed terminal check.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '120s';

DO $requires_sep18_published_rerun295$
DECLARE
  v_cost_schema JSONB;
  v_publication_definition TEXT;
BEGIN
  IF pg_catalog.to_regprocedure(
       'public.lab_arena_open_scoring_v2(text,smallint,jsonb)'
     ) IS NULL
     OR pg_catalog.to_regprocedure(
       'public.lab_arena__successful_call_cost_state(text,text,text)'
     ) IS NULL
     OR pg_catalog.to_regprocedure(
       'public.lab_arena_per_icp_cost_schema_v1()'
     ) IS NULL
     OR pg_catalog.to_regprocedure(
       'public.lab_arena__successful_icp_cost_state(text,text,integer)'
     ) IS NULL
     OR pg_catalog.to_regclass('public.lab_arena_rounds') IS NULL
     OR pg_catalog.to_regclass('public.lab_arena_submissions') IS NULL
     OR pg_catalog.to_regclass('public.lab_arena_runs') IS NULL
     OR pg_catalog.to_regclass('public.lab_arena_ledger') IS NULL THEN
    RAISE EXCEPTION 'apply current Arena schema before rerun295';
  END IF;
  SELECT public.lab_arena_per_icp_cost_schema_v1() INTO v_cost_schema;
  IF v_cost_schema IS DISTINCT FROM
       '{"schema_version":"leadpoet.lab_arena.per_icp_cost_schema.v1",'
       '"version":289,"policy":"successful_calls_per_icp_v1"}'::JSONB THEN
    RAISE EXCEPTION 'Sep18 rerun295 per-ICP cost schema differs';
  END IF;
  SELECT pg_catalog.pg_get_functiondef(
    'public.lab_arena__per_icp_publication_valid(text,jsonb)'::pg_catalog.regprocedure
  ) INTO v_publication_definition;
  IF pg_catalog.strpos(
       v_publication_definition, 'lab_arena_per_icp_null_final_score_v1'
     ) = 0
     OR pg_catalog.strpos(v_publication_definition, 'v_accepted_count') = 0
     OR pg_catalog.strpos(v_publication_definition, 'v_is_baseline') = 0 THEN
    RAISE EXCEPTION 'apply migration 292 before rerun295';
  END IF;
END;
$requires_sep18_published_rerun295$;

GRANT CREATE ON SCHEMA public TO lab_arena_owner;

-- Keep the normal driver. Change only the admitted Sep18 baseline assignment
-- suffix and require the exact current integrity scorer definition.
DO $bind_rerun295_score_namespace$
DECLARE
  v_definition TEXT;
  v_old_assignment TEXT := $old$
    v_assignment := p_round_id || ':' || v_scored.submission_id || ':' ||
      p_stage::TEXT || ':' || v_scored.icp_position::TEXT || ':score' ||
      CASE WHEN p_round_id = 'arena-2026-09-17'
                  AND v_scored.submission_id = 'baseline-2026-09-17'
                  AND EXISTS (
                    SELECT 1 FROM public.lab_arena_rounds
                    WHERE round_id = 'arena-2026-09-17-rerun285archive'
                  )
           THEN ':rerun286' ELSE '' END;
$old$;
  v_new_assignment TEXT := $new$
    v_assignment := p_round_id || ':' || v_scored.submission_id || ':' ||
      p_stage::TEXT || ':' || v_scored.icp_position::TEXT || ':score' ||
      CASE WHEN p_round_id = 'arena-2026-09-17'
                  AND v_scored.submission_id = 'baseline-2026-09-17'
                  AND EXISTS (
                    SELECT 1 FROM public.lab_arena_rounds
                    WHERE round_id = 'arena-2026-09-17-rerun285archive'
                  )
           THEN ':rerun286'
           WHEN p_round_id = 'arena-2026-09-18'
                  AND v_scored.submission_id = 'baseline-2026-09-18'
                  AND EXISTS (
                    SELECT 1 FROM public.lab_arena_rounds
                    WHERE round_id = 'arena-2026-09-18-rerun291archive'
                  )
           THEN ':rerun295' ELSE '' END;
$new$;
BEGIN
  v_definition := pg_catalog.pg_get_functiondef(
    'public.lab_arena_open_scoring_v2(text,smallint,jsonb)'::pg_catalog.regprocedure
  );
  IF pg_catalog.strpos(
       v_definition, 'lab_arena_judgment_cache_source_invalid'
     ) = 0 THEN
    RAISE EXCEPTION 'current integrity scoring definition differs';
  END IF;
  IF pg_catalog.strpos(v_definition, v_old_assignment) <> 0
     AND pg_catalog.strpos(
       pg_catalog.substr(
         v_definition, pg_catalog.strpos(v_definition, v_old_assignment)
           + pg_catalog.length(v_old_assignment)
       ), v_old_assignment
     ) = 0
     AND pg_catalog.strpos(v_definition, v_new_assignment) = 0 THEN
    IF pg_catalog.encode(extensions.digest(v_definition, 'sha256'), 'hex')
         IS DISTINCT FROM '1bb24448bf3d2e0aaf92dd7e140b710e7a19f34e2f949bc6c8e079a10a0508cf' THEN
      RAISE EXCEPTION 'current integrity scoring definition differs';
    END IF;
    v_definition := pg_catalog.replace(
      v_definition, v_old_assignment, v_new_assignment
    );
    EXECUTE v_definition;
  ELSIF pg_catalog.strpos(v_definition, v_old_assignment) = 0
     AND pg_catalog.strpos(v_definition, v_new_assignment) <> 0
     AND pg_catalog.strpos(
       pg_catalog.substr(
         v_definition, pg_catalog.strpos(v_definition, v_new_assignment)
           + pg_catalog.length(v_new_assignment)
       ), v_new_assignment
     ) = 0 THEN
    IF pg_catalog.encode(extensions.digest(
         pg_catalog.replace(v_definition, v_new_assignment, v_old_assignment),
         'sha256'), 'hex') IS DISTINCT FROM '1bb24448bf3d2e0aaf92dd7e140b710e7a19f34e2f949bc6c8e079a10a0508cf' THEN
      RAISE EXCEPTION 'current integrity scoring definition differs';
    END IF;
  ELSE
    RAISE EXCEPTION 'current integrity scoring namespace binding differs';
  END IF;
END;
$bind_rerun295_score_namespace$;

CREATE OR REPLACE FUNCTION public.lab_arena_sep18_published_rerun295_score_namespace_guard_v1()
RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public
AS $sep18_published_rerun295_score_namespace_guard$
BEGIN
  IF NEW.round_id = 'arena-2026-09-18'
     AND NEW.submission_id = 'baseline-2026-09-18'
     AND NEW.kind = 'score'
     AND EXISTS (
       SELECT 1 FROM public.lab_arena_rounds
       WHERE round_id = 'arena-2026-09-18-rerun291archive'
     )
     AND NEW.assignment_id IS DISTINCT FROM
           NEW.round_id || ':' || NEW.submission_id || ':' ||
           NEW.stage::TEXT || ':' || NEW.icp_position::TEXT ||
           ':score:rerun295' THEN
    RAISE EXCEPTION 'Sep18 rerun295 scoring requires exact baseline namespace'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$sep18_published_rerun295_score_namespace_guard$;
ALTER FUNCTION public.lab_arena_sep18_published_rerun295_score_namespace_guard_v1()
  OWNER TO lab_arena_owner;
REVOKE ALL ON FUNCTION public.lab_arena_sep18_published_rerun295_score_namespace_guard_v1()
  FROM PUBLIC, anon, authenticated, service_role, lab_arena_service;
DROP TRIGGER IF EXISTS lab_arena_sep18_published_rerun295_score_namespace_guard
  ON public.lab_arena_runs;
CREATE TRIGGER lab_arena_sep18_published_rerun295_score_namespace_guard
  BEFORE INSERT ON public.lab_arena_runs
  FOR EACH ROW
  EXECUTE FUNCTION public.lab_arena_sep18_published_rerun295_score_namespace_guard_v1();

