  v_terminal_baseline CONSTANT JSONB :=
    $terminal_baseline${"status": "frozen", "consent": {"public_rerun": true}, "is_king": true, "round_id": "arena-2026-09-18", "frozen_at": "2026-09-18T00:00:06.889287+00:00", "created_at": "2026-09-18T00:00:06.512576+00:00", "source_ref": "arena/arena-2026-09-18/sources/baseline-2026-09-18.tar.gz", "updated_at": "2026-09-18T00:00:06.889532+00:00", "accepted_at": "2026-09-18T00:00:06.644863+00:00", "miner_hotkey": "5FNVgRnrxMibhcBGEAaajGrYjsaCn441a5HuGUBUNnxEBLo9", "owner_coldkey": null, "submission_id": "baseline-2026-09-18", "rejection_rule": null, "submission_doc": {"consent": {"public_rerun": true}, "is_king": true, "source_ref": "arena/arena-2026-09-18/sources/baseline-2026-09-18.tar.gz", "source_size_bytes": 604847}, "code_review_doc": null, "owner_block_hash": null, "code_review_claim": null, "source_size_bytes": 604847, "code_review_status": "pending", "owner_block_number": null, "code_review_attempts": 0, "code_review_expires_at": null, "code_review_started_at": null, "replaces_submission_id": null, "replaced_by_submission_id": null}$terminal_baseline$::JSONB;
  v_runs_hash TEXT;
  v_ledger_hash TEXT;
BEGIN
  SELECT 'sha256:' || pg_catalog.encode(extensions.digest(
    COALESCE(pg_catalog.string_agg(pg_catalog.encode(extensions.digest(
