    AND EXISTS (
      SELECT 1 FROM public.lab_arena_submissions AS archived
      WHERE archived.round_id = 'arena-2026-09-18-rerun291archive'
        AND archived.submission_id = 'baseline-2026-09-18-rerun291archive'
        AND (pg_catalog.to_jsonb(archived) - 'round_id' - 'submission_id') =
          (v_terminal_baseline - 'round_id' - 'submission_id')
        AND source_ref = 'arena/arena-2026-09-18/sources/baseline-2026-09-18.tar.gz'
        AND source_size_bytes = 604847
        AND submission_doc ->> 'source_ref' =
          'arena/arena-2026-09-18/sources/baseline-2026-09-18.tar.gz'
        AND (submission_doc ->> 'source_size_bytes')::BIGINT =
          604847
        AND (NOT submission_doc ? 'source_sha256'
             OR submission_doc ->> 'source_sha256' = '7e1bb0747014a57bc50f48f9f822d1a7c936682d63f06564e978d23f54eb7fc1')
        AND (NOT submission_doc ? 'source_commit'
             OR submission_doc ->> 'source_commit' = 'e5341f85829ad196b4a1cb58b38a34155697c8d4')
    )
    AND (SELECT pg_catalog.count(*) FROM public.lab_arena_runs
         WHERE round_id = 'arena-2026-09-18-rerun291archive'
           AND submission_id = 'baseline-2026-09-18-rerun291archive') =
