      WHERE round_id = 'arena-2026-09-18-rerun291archive'
        AND submission_id <> 'baseline-2026-09-18-rerun291archive'
    )
    AND v_runs_hash = 'sha256:a59b76561c71c0116d564cba8e21fa5368110b8675971d5152a6660a1fe203e0'
    AND v_ledger_hash = 'sha256:2f1bf84b85976f01862680e32e20195bfb2906dac58a67da4bda247fc75a9099'
