CREATE OR REPLACE FUNCTION public.lab_arena_sep18_published_rerun295_nonbaseline_valid_v1()
RETURNS BOOLEAN
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public, extensions
AS $sep18_published_rerun295_nonbaseline_valid$
DECLARE
  v_submissions_hash TEXT;
  v_runs_hash TEXT;
  v_ledger_hash TEXT;
BEGIN
  SELECT 'sha256:' || pg_catalog.encode(extensions.digest(
    COALESCE(pg_catalog.string_agg(pg_catalog.encode(extensions.digest(
      pg_catalog.to_jsonb(row_value)::TEXT, 'sha256'
    ), 'hex'), '' ORDER BY submission_id), ''), 'sha256'), 'hex')
  INTO v_submissions_hash
  FROM public.lab_arena_submissions AS row_value
  WHERE round_id = 'arena-2026-09-18'
    AND submission_id <> 'baseline-2026-09-18';
  SELECT 'sha256:' || pg_catalog.encode(extensions.digest(
    COALESCE(pg_catalog.string_agg(pg_catalog.encode(extensions.digest(
      pg_catalog.to_jsonb(row_value)::TEXT, 'sha256'
    ), 'hex'), '' ORDER BY run_id), ''), 'sha256'), 'hex')
  INTO v_runs_hash
  FROM public.lab_arena_runs AS row_value
  WHERE round_id = 'arena-2026-09-18'
    AND submission_id <> 'baseline-2026-09-18';
  SELECT 'sha256:' || pg_catalog.encode(extensions.digest(
    COALESCE(pg_catalog.string_agg(pg_catalog.encode(extensions.digest(
      pg_catalog.to_jsonb(row_value)::TEXT, 'sha256'
    ), 'hex'), '' ORDER BY entry_id), ''), 'sha256'), 'hex')
  INTO v_ledger_hash
  FROM public.lab_arena_ledger AS row_value
  WHERE round_id = 'arena-2026-09-18'
    AND submission_id <> 'baseline-2026-09-18';
  RETURN (SELECT pg_catalog.count(*) FROM public.lab_arena_submissions
          WHERE round_id = 'arena-2026-09-18'
            AND submission_id <> 'baseline-2026-09-18') =
           4
     AND (SELECT pg_catalog.count(*) FROM public.lab_arena_runs
          WHERE round_id = 'arena-2026-09-18'
            AND submission_id <> 'baseline-2026-09-18') =
           160
     AND (SELECT pg_catalog.count(*) FROM public.lab_arena_ledger
          WHERE round_id = 'arena-2026-09-18'
            AND submission_id <> 'baseline-2026-09-18') =
           2898
     AND v_submissions_hash = 'sha256:40318c429446ccfc8e2ad48a1bec6ce640e526f453062bd9e4302c0ca5d8a221'
     AND v_runs_hash = 'sha256:b8ccce62297864d49d97d560433197edbf0d39a1b520b1c6b6cbf85acaab17f9'
     AND v_ledger_hash = 'sha256:653f43475f13600d3a216f1f1b527d386721426930cda113794340699cb57fbc';
END;
$sep18_published_rerun295_nonbaseline_valid$;
ALTER FUNCTION public.lab_arena_sep18_published_rerun295_nonbaseline_valid_v1()
  OWNER TO lab_arena_owner;
REVOKE ALL ON FUNCTION public.lab_arena_sep18_published_rerun295_nonbaseline_valid_v1()
  FROM PUBLIC, anon, authenticated, service_role, lab_arena_service;

