79970e02a303e6c3b10f5155b3c33b:2:19:1.json", "icp_position": 19, "scored_run_id": "arena-2026-09-18:sub-e079970e02a303e6c3b10f5155b3c33b:2:19:1", "submission_id": "sub-e079970e02a303e6c3b10f5155b3c33b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:10:1.json", "icp_position": 10, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:10:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:11:1.json", "icp_position": 11, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:11:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:12:1.json", "icp_position": 12, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:12:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:13:1.json", "icp_position": 13, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:13:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:14:1.json", "icp_position": 14, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:14:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:15:1.json", "icp_position": 15, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:15:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:16:1.json", "icp_position": 16, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:16:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:17:1.json", "icp_position": 17, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:17:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:18:1.json", "icp_position": 18, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:18:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:19:1.json", "icp_position": 19, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:19:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}], "schema_version": "leadpoet.lab_arena.scoring_plan.v1"}, "stage3_scoring_plan_doc": null, "champion_fallback_providers": []}$terminal_round$::JSONB;
  v_terminal_baseline CONSTANT JSONB :=
    $terminal_baseline${"status": "frozen", "consent": {"public_rerun": true}, "is_king": true, "round_id": "arena-2026-09-18", "frozen_at": "2026-09-18T00:00:06.889287+00:00", "created_at": "2026-09-18T00:00:06.512576+00:00", "source_ref": "arena/arena-2026-09-18/sources/baseline-2026-09-18.tar.gz", "updated_at": "2026-09-18T00:00:06.889532+00:00", "accepted_at": "2026-09-18T00:00:06.644863+00:00", "miner_hotkey": "5FNVgRnrxMibhcBGEAaajGrYjsaCn441a5HuGUBUNnxEBLo9", "owner_coldkey": null, "submission_id": "baseline-2026-09-18", "rejection_rule": null, "submission_doc": {"consent": {"public_rerun": true}, "is_king": true, "source_ref": "arena/arena-2026-09-18/sources/baseline-2026-09-18.tar.gz", "source_size_bytes": 604847}, "code_review_doc": null, "owner_block_hash": null, "code_review_claim": null, "source_size_bytes": 604847, "code_review_status": "pending", "owner_block_number": null, "code_review_attempts": 0, "code_review_expires_at": null, "code_review_started_at": null, "replaces_submission_id": null, "replaced_by_submission_id": null}$terminal_baseline$::JSONB;
  v_forward_schedule CONSTANT JSONB :=
    $forward_schedule${"benchmark_deadline":"2026-09-18T09:00:00Z","final_scoring_close":"2026-09-18T22:30:03Z","publication_deadline":"2026-09-18T22:30:04Z","stage_1_close":"2026-09-18T16:30:01Z","stage_1_scoring_close":"2026-09-18T19:30:01Z","stage_1_start":"2026-09-18T09:00:01Z","stage_2_close":"2026-09-18T19:30:03Z","stage_2_start":"2026-09-18T19:30:02Z","submission_cutoff":"2026-09-18T00:00:00Z","submission_open":"2026-09-17T00:00:00Z"}$forward_schedule$::JSONB;
  v_round public.lab_arena_rounds%ROWTYPE;
  v_baseline public.lab_arena_submissions%ROWTYPE;
  v_new_configuration JSONB;
  v_new_participants JSONB;
  v_archive_configuration JSONB;
  v_expected_round JSONB;
  v_expected_baseline JSONB;
  v_protected_before JSONB;
  v_protected_after JSONB;
  v_unsettled_cost_count BIGINT;
  v_runs_hash TEXT;
  v_ledger_hash TEXT;
  v_position INTEGER;
  v_stage SMALLINT;
  v_assignment TEXT;
  v_count BIGINT;
BEGIN
  PERFORM pg_catalog.set_config('lock_timeout', '5s', TRUE);
  PERFORM pg_catalog.set_config('statement_timeout', '120s', TRUE);
  IF p_source_size_bytes IS DISTINCT FROM 641923
     OR p_source_sha256 IS DISTINCT FROM '1ba24d1abac3849b8900238cb3f8f2ced3aab41fbe8f30064c0dcbeefc9c3cd3'
     OR p_source_commit IS DISTINCT FROM 'e21d29698edb60e6b5635f5f27e5a0058709210f'
     OR p_bank_sha256 IS DISTINCT FROM v_bank_sha256
     OR p_forward_schedule IS DISTINCT FROM v_forward_schedule THEN
    RAISE EXCEPTION 'Sep18 rerun295 source, bank, or schedule differs'
      USING ERRCODE = '22023';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('arena-2026-09-18-published-rerun295', 0)
  );
  LOCK TABLE public.lab_arena_rounds IN ACCESS EXCLUSIVE MODE;
  LOCK TABLE public.lab_arena_submissions IN ACCESS EXCLUSIVE MODE;
  LOCK TABLE public.lab_arena_runs IN ACCESS EXCLUSIVE MODE;
  LOCK TABLE public.lab_arena_ledger IN ACCESS EXCLUSIVE MODE;
  SELECT * INTO STRICT v_round FROM public.lab_arena_rounds
  WHERE round_id = v_round_id FOR UPDATE;
  SELECT * INTO STRICT v_baseline FROM public.lab_arena_submissions
  WHERE round_id = v_round_id AND submission_id = v_baseline_id FOR UPDATE;

  v_new_configuration := pg_catalog.jsonb_set(
    pg_catalog.jsonb_set(
      v_terminal_round -> 'configuration_doc',
      '{schedule}', v_forward_schedule, FALSE
    ),
    '{baseline_source_url}',
    pg_catalog.to_jsonb(
      'https://github.com/leadpoet/leadpoet-sales-agent/archive/refs/heads/lab.tar.gz'::TEXT
    ),
    FALSE
  );
  SELECT pg_catalog.jsonb_agg(
    CASE WHEN item ->> 'submission_id' = v_baseline_id THEN
      item || pg_catalog.jsonb_build_object(
        'source_ref', v_source_ref,
        'source_size_bytes', p_source_size_bytes
      ) ELSE item END ORDER BY ordinal
  ) INTO v_new_participants
  FROM pg_catalog.jsonb_array_elements(v_terminal_round -> 'participants')
    WITH ORDINALITY AS entries(item, ordinal);

  -- Response-loss replay is read-only and verifies both namespaces.
  IF EXISTS (SELECT 1 FROM public.lab_arena_rounds
             WHERE round_id = v_archive_round_id)
     OR v_baseline.source_ref = v_source_ref
     OR EXISTS (
       SELECT 1 FROM public.lab_arena_runs
       WHERE round_id = v_round_id AND submission_id = v_baseline_id
         AND assignment_id LIKE '%:rerun295'
     ) THEN
    IF public.lab_arena_sep18_rerun291_archive_valid295_v1() IS NOT TRUE
       OR v_round.configuration_doc IS DISTINCT FROM v_new_configuration
       OR v_round.participants IS DISTINCT FROM v_new_participants
       OR v_round.status NOT IN (
         'stage1', 'stage1_closed', 'stage1_scoring', 'stage1_judged',
         'stage1_scored', 'stage2', 'stage2_closed', 'stage2_scoring',
         'stage2_judged', 'scored', 'published'
       )
       OR v_round.reward_basis_hash IS DISTINCT FROM
            v_terminal_round ->> 'reward_basis_hash'
       OR v_round.reward_basis_doc IS DISTINCT FROM
            v_terminal_round -> 'reward_basis_doc'
       OR v_round.signing_key_doc IS DISTINCT FROM
            v_terminal_round -> 'signing_key_doc'
       OR v_round.effective_reward_epoch IS DISTINCT FROM
            (v_terminal_round ->> 'effective_reward_epoch')::BIGINT
       OR v_round.reward_activated_at IS DISTINCT FROM
            (v_terminal_round ->> 'reward_activated_at')::TIMESTAMPTZ
       OR v_round.king_outcome IS DISTINCT FROM
            v_terminal_round ->> 'king_outcome'
       OR v_round.king_hotkey IS DISTINCT FROM
            v_terminal_round ->> 'king_hotkey'
       OR v_round.king_start_epoch IS DISTINCT FROM
            (v_terminal_round ->> 'king_start_epoch')::BIGINT
       OR v_round.promotion_required IS DISTINCT FROM
            (v_terminal_round ->> 'promotion_required')::BOOLEAN
       OR v_round.promotion_doc IS DISTINCT FROM
            NULLIF(v_terminal_round -> 'promotion_doc', 'null'::JSONB)
       OR v_round.baseline_promoted_at IS DISTINCT FROM
            (v_terminal_round ->> 'baseline_promoted_at')::TIMESTAMPTZ
       OR v_round.champion_funding_frozen IS DISTINCT FROM
            (v_terminal_round ->> 'champion_funding_frozen')::BOOLEAN
       OR v_round.champion_submission_id IS DISTINCT FROM
            v_terminal_round ->> 'champion_submission_id'
       OR v_round.champion_hotkey IS DISTINCT FROM
            v_terminal_round ->> 'champion_hotkey'
       OR v_round.champion_fallback_providers IS DISTINCT FROM
            ARRAY(SELECT pg_catalog.jsonb_array_elements_text(
              COALESCE(v_terminal_round -> 'champion_fallback_providers', '[]'::JSONB)
            ))
       OR v_baseline.source_ref IS DISTINCT FROM v_source_ref
       OR v_baseline.source_size_bytes IS DISTINCT FROM p_source_size_bytes
       OR v_baseline.submission_doc ->> 'source_ref' IS DISTINCT FROM v_source_ref
       OR (v_baseline.submission_doc ->> 'source_size_bytes')::BIGINT
            IS DISTINCT FROM p_source_size_bytes
       OR v_baseline.submission_doc ->> 'source_sha256'
            IS DISTINCT FROM p_source_sha256
       OR v_baseline.submission_doc ->> 'source_commit'
            IS DISTINCT FROM p_source_commit
       OR (SELECT pg_catalog.count(DISTINCT assignment_id)
           FROM public.lab_arena_runs
           WHERE round_id = v_round_id AND submission_id = v_baseline_id
             AND kind = 'execute' AND assignment_id LIKE '%:rerun295') <> 20
       OR EXISTS (
         SELECT 1 FROM public.lab_arena_runs
         WHERE round_id = v_round_id AND submission_id = v_baseline_id
           AND kind = 'score'
           AND assignment_id NOT LIKE '%:score:rerun295'
       ) THEN
      RAISE EXCEPTION 'Sep18 rerun295 replay differs' USING ERRCODE = '55000';
    END IF;
    RETURN pg_catalog.jsonb_build_object(
      'status', 'existing', 'round_id', v_round_id,
      'baseline_execute_assignments', 20,
      'execute_namespace', 'rerun295',
      'score_namespace', 'score:rerun295',
      'source_size_bytes', p_source_size_bytes,
      'source_sha256', p_source_sha256,
      'source_commit', p_source_commit
    );
  END IF;

  IF (p_forward_schedule ->> 'benchmark_deadline')::TIMESTAMPTZ <=
       pg_catalog.clock_timestamp() THEN
    RAISE EXCEPTION 'Sep18 rerun295 admission window has closed'
      USING ERRCODE = '22023';
  END IF;
  SELECT pg_catalog.count(*) INTO v_unsettled_cost_count
  FROM public.lab_arena_submissions AS submission
  CROSS JOIN (VALUES ('execute'::TEXT), ('score'::TEXT)) AS kinds(kind)
  CROSS JOIN LATERAL (
    SELECT public.lab_arena__successful_call_cost_state(
      submission.submission_id, kinds.kind, NULL
    ) AS state
  ) AS costs
  WHERE submission.round_id = v_round_id
    AND (
      COALESCE((costs.state ->> 'inflight_calls')::BIGINT, -1) <> 0
      OR COALESCE((costs.state ->> 'success_unresolved_calls')::BIGINT, -1) <> 0
    );
  SELECT 'sha256:' || pg_catalog.encode(extensions.digest(
    COALESCE(pg_catalog.string_agg(pg_catalog.encode(extensions.digest(
      (pg_catalog.to_jsonb(row_value) - 'round_id' - 'submission_id')::TEXT,
      'sha256'), 'hex'), '' ORDER BY run_id), ''), 'sha256'), 'hex')
  INTO v_runs_hash FROM public.lab_arena_runs AS row_value
  WHERE round_id = v_round_id AND submission_id = v_baseline_id;
  SELECT 'sha256:' || pg_catalog.encode(extensions.digest(
    COALESCE(pg_catalog.string_agg(pg_catalog.encode(extensions.digest(
      (pg_catalog.to_jsonb(row_value) - 'round_id' - 'submission_id')::TEXT,
      'sha256'), 'hex'), '' ORDER BY entry_id), ''), 'sha256'), 'hex')
  INTO v_ledger_hash FROM public.lab_arena_ledger AS row_value
  WHERE round_id = v_round_id AND submission_id = v_baseline_id;
  IF pg_catalog.to_jsonb(v_round) IS DISTINCT FROM v_terminal_round
     OR pg_catalog.to_jsonb(v_baseline) IS DISTINCT FROM v_terminal_baseline
     OR v_round.status IS DISTINCT FROM 'published'
     OR v_round.evaluation_date IS DISTINCT FROM '2026-09-18'
     OR v_round.icp_set_date IS DISTINCT FROM '2026-09-17'
     OR v_round.benchmark_ref IS DISTINCT FROM
          'arena/arena-2026-09-18/benchmark.json'
     OR v_round.reward_basis_hash IS NULL
     OR v_round.reward_basis_doc IS NULL
     OR v_round.signing_key_doc IS NULL
     OR v_round.effective_reward_epoch IS NULL
     OR v_round.reward_activated_at IS NULL
     OR v_round.king_outcome IS NULL
     OR v_round.king_outcome NOT IN ('crowned', 'no_king')
     OR pg_catalog.jsonb_typeof(v_round.publication_doc -> 'king_decision')
          IS DISTINCT FROM 'object'
     OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(
           v_round.publication_doc -> 'king_decision')) <> 4
     OR NOT (v_round.publication_doc -> 'king_decision' ?& ARRAY[
          'outcome', 'king_submission_id', 'king_hotkey', 'winner_submission_id'
        ])
     OR (
       v_round.promotion_required
       AND v_round.publication_doc #>> '{king_decision,outcome}' = 'crowned'
       AND (v_round.promotion_doc IS NULL OR v_round.baseline_promoted_at IS NULL)
     )
     OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_array_elements(
           v_round.participants)) <> 5
     OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_array_elements(
           v_round.participants) AS participant
         WHERE NOT COALESCE((participant ->> 'is_king')::BOOLEAN, FALSE)) <> 4
     OR v_round.configuration_doc ->> 'sourcing_cost_eligibility_policy'
          IS DISTINCT FROM 'successful_calls_per_icp_v1'
     OR (v_round.configuration_doc ->> 'execution_icp_cap_microusd')::BIGINT
          IS DISTINCT FROM 4000000
     OR (v_round.configuration_doc ->> 'cost_per_company_microusd')::BIGINT
          IS DISTINCT FROM 800000
     OR v_baseline.source_ref IS DISTINCT FROM v_terminal_source_ref
     OR v_baseline.source_size_bytes IS DISTINCT FROM 604847
     OR v_baseline.submission_doc ->> 'source_ref'
          IS DISTINCT FROM v_terminal_source_ref
     OR (v_baseline.submission_doc ->> 'source_size_bytes')::BIGINT
          IS DISTINCT FROM 604847
     OR (v_baseline.submission_doc ? 'source_sha256'
         AND v_baseline.submission_doc ->> 'source_sha256'
             IS DISTINCT FROM '7e1bb0747014a57bc50f48f9f822d1a7c936682d63f06564e978d23f54eb7fc1')
     OR (v_baseline.submission_doc ? 'source_commit'
         AND v_baseline.submission_doc ->> 'source_commit'
             IS DISTINCT FROM 'e5341f85829ad196b4a1cb58b38a34155697c8d4')
     OR (SELECT pg_catalog.count(*) FROM public.lab_arena_runs
         WHERE round_id = v_round_id AND submission_id = v_baseline_id) <>
        51
     OR (SELECT pg_catalog.count(*) FROM public.lab_arena_ledger
         WHERE round_id = v_round_id AND submission_id = v_baseline_id) <>
        11025
     OR v_runs_hash IS DISTINCT FROM 'sha256:a59b76561c71c0116d564cba8e21fa5368110b8675971d5152a6660a1fe203e0'
     OR v_ledger_hash IS DISTINCT FROM 'sha256:2f1bf84b85976f01862680e32e20195bfb2906dac58a67da4bda247fc75a9099'
     OR EXISTS (SELECT 1 FROM public.lab_arena_runs
                WHERE round_id = v_round_id
                  AND status IN ('pending', 'leased', 'submitted'))
     OR v_unsettled_cost_count <> 0
     OR EXISTS (SELECT 1 FROM public.lab_arena_rounds
                WHERE round_id = v_archive_round_id)
     OR public.lab_arena_sep18_published_rerun295_nonbaseline_valid_v1() IS NOT TRUE THEN
    RAISE EXCEPTION 'Sep18 published terminal differs'
      USING ERRCODE = '55000';
  END IF;

  -- Preserve every unrelated round, submission, run, ledger row, and accepted
  -- weight state. Only the exact Sep18 baseline rows move to the shadow archive.
  SELECT pg_catalog.jsonb_build_object(
    'rounds', (SELECT pg_catalog.jsonb_build_object(
      'count', pg_catalog.count(*), 'sha256', 'sha256:' || pg_catalog.encode(
        extensions.digest(COALESCE(pg_catalog.string_agg(pg_catalog.encode(
          extensions.digest(pg_catalog.to_jsonb(row_value)::TEXT, 'sha256'),
          'hex'), '' ORDER BY round_id), ''), 'sha256'), 'hex'))
      FROM public.lab_arena_rounds AS row_value
      WHERE round_id <> v_round_id),
    'submissions', (SELECT pg_catalog.jsonb_build_object(
      'count', pg_catalog.count(*), 'sha256', 'sha256:' || pg_catalog.encode(
        extensions.digest(COALESCE(pg_catalog.string_agg(pg_catalog.encode(
          extensions.digest(pg_catalog.to_jsonb(row_value)::TEXT, 'sha256'),
          'hex'), '' ORDER BY round_id, submission_id), ''), 'sha256'), 'hex'))
      FROM public.lab_arena_submissions AS row_value
      WHERE NOT (round_id = v_round_id AND submission_id = v_baseline_id)),
    'runs', (SELECT pg_catalog.jsonb_build_object(
      'count', pg_catalog.count(*), 'sha256', 'sha256:' || pg_catalog.encode(
        extensions.digest(COALESCE(pg_catalog.string_agg(pg_catalog.encode(
          extensions.digest(pg_catalog.to_jsonb(row_value)::TEXT, 'sha256'),
          'hex'), '' ORDER BY run_id), ''), 'sha256'), 'hex'))
      FROM public.lab_arena_runs AS row_value
      WHERE NOT (round_id = v_round_id AND submission_id = v_baseline_id)),
    -- Bound billing preservation to rounds that the transition can affect or
    -- race with. Older ledger rows cannot match its exact mutation predicate.
    'ledger', (SELECT pg_catalog.jsonb_build_object(
      'count', pg_catalog.count(*), 'sha256', 'sha256:' || pg_catalog.encode(
        extensions.digest(COALESCE(pg_catalog.string_agg(pg_catalog.encode(
          extensions.digest(pg_catalog.to_jsonb(row_value)::TEXT, 'sha256'),
          'hex'), '' ORDER BY entry_id), ''), 'sha256'), 'hex'))
      FROM public.lab_arena_ledger AS row_value
      WHERE round_id IN (v_round_id, 'arena-2026-09-19',
                         'arena-2026-09-17-rerun285archive')
        AND NOT (round_id = v_round_id AND submission_id = v_baseline_id)),
    'weights', (SELECT pg_catalog.jsonb_build_object(
      'count', pg_catalog.count(*), 'sha256', 'sha256:' || pg_catalog.encode(
        extensions.digest(COALESCE(pg_catalog.string_agg(pg_catalog.encode(
          extensions.digest(pg_catalog.to_jsonb(row_value)::TEXT, 'sha256'),
          'hex'), '' ORDER BY network, netuid, epoch), ''), 'sha256'), 'hex'))
      FROM public.lab_arena_accepted_weight_states AS row_value)
  ) INTO v_protected_before;

  v_archive_configuration := (v_terminal_round -> 'configuration_doc') ||
    pg_catalog.jsonb_build_object(
      'round_id', v_archive_round_id, 'mode', 'shadow', 'rewards_enabled', FALSE
    );
  ALTER TABLE public.lab_arena_rounds DISABLE TRIGGER USER;
  ALTER TABLE public.lab_arena_submissions DISABLE TRIGGER USER;
  ALTER TABLE public.lab_arena_runs DISABLE TRIGGER USER;
  ALTER TABLE public.lab_arena_ledger DISABLE TRIGGER USER;
  INSERT INTO public.lab_arena_rounds (
    round_id, status, configuration_doc, rewards_enabled, cancel_reason
  ) VALUES (
    v_archive_round_id, 'cancelled', v_archive_configuration, FALSE,
    'authorized_sep18_rerun291_baseline_archive'
  );
  INSERT INTO public.lab_arena_submissions
  SELECT (pg_catalog.jsonb_populate_record(
    NULL::public.lab_arena_submissions,
    v_terminal_baseline || pg_catalog.jsonb_build_object(
      'submission_id', v_archive_submission_id, 'round_id', v_archive_round_id
    )
  )).*;
  UPDATE public.lab_arena_runs
  SET round_id = v_archive_round_id,
      submission_id = v_archive_submission_id
  WHERE round_id = v_round_id AND submission_id = v_baseline_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> 51 THEN
    RAISE EXCEPTION 'Sep18 rerun295 run archive count differs';
  END IF;
  UPDATE public.lab_arena_ledger
  SET round_id = v_archive_round_id,
      submission_id = v_archive_submission_id
  WHERE round_id = v_round_id AND submission_id = v_baseline_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> 11025 THEN
    RAISE EXCEPTION 'Sep18 rerun295 ledger archive count differs';
  END IF;
  UPDATE public.lab_arena_submissions
  SET source_ref = v_source_ref,
      source_size_bytes = p_source_size_bytes,
      submission_doc = COALESCE(submission_doc, '{}'::JSONB) ||
        pg_catalog.jsonb_build_object(
          'source_ref', v_source_ref,
          'source_size_bytes', p_source_size_bytes,
          'source_sha256', p_source_sha256,
          'source_commit', p_source_commit
        )
  WHERE round_id = v_round_id AND submission_id = v_baseline_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sep18 rerun295 baseline update differs';
  END IF;
  UPDATE public.lab_arena_rounds
  SET status = 'stage1',
      status_generation = status_generation + 1,
      stage_generation = stage_generation + 1,
      configuration_doc = v_new_configuration,
      participants = v_new_participants,
      stage1_scoring_plan_doc = NULL,
      stage2_scoring_plan_doc = NULL,
      stage3_scoring_plan_doc = NULL,
      finalists = NULL,
      publication_doc = NULL,
      published_at = NULL,
      cancel_reason = NULL,
      updated_at = pg_catalog.clock_timestamp()
  WHERE round_id = v_round_id;
  FOR v_position IN 0 .. 19 LOOP
    v_stage := CASE WHEN v_position < 10 THEN 1 ELSE 2 END;
    v_assignment := v_round_id || ':' || v_baseline_id || ':' ||
      v_stage::TEXT || ':' || v_position::TEXT || ':rerun295';
    INSERT INTO public.lab_arena_runs (
      run_id, assignment_id, round_id, submission_id, miner_hotkey,
      stage, icp_position, attempt, kind, status, stage_generation
    ) VALUES (
      v_assignment || ':1', v_assignment, v_round_id, v_baseline_id,
      v_baseline.miner_hotkey, v_stage, v_position, 1, 'execute', 'pending',
      v_round.stage_generation + 1
    );
  END LOOP;
  ALTER TABLE public.lab_arena_ledger ENABLE TRIGGER USER;
  ALTER TABLE public.lab_arena_runs ENABLE TRIGGER USER;
  ALTER TABLE public.lab_arena_submissions ENABLE TRIGGER USER;
  ALTER TABLE public.lab_arena_rounds ENABLE TRIGGER USER;

  SELECT pg_catalog.jsonb_build_object(
    'rounds', (SELECT pg_catalog.jsonb_build_object(
      'count', pg_catalog.count(*), 'sha256', 'sha256:' || pg_catalog.encode(
        extensions.digest(COALESCE(pg_catalog.string_agg(pg_catalog.encode(
          extensions.digest(pg_catalog.to_jsonb(row_value)::TEXT, 'sha256'),
          'hex'), '' ORDER BY round_id), ''), 'sha256'), 'hex'))
      FROM public.lab_arena_rounds AS row_value
      WHERE round_id <> v_round_id AND round_id <> v_archive_round_id),
    'submissions', (SELECT pg_catalog.jsonb_build_object(
      'count', pg_catalog.count(*), 'sha256', 'sha256:' || pg_catalog.encode(
        extensions.digest(COALESCE(pg_catalog.string_agg(pg_catalog.encode(
          extensions.digest(pg_catalog.to_jsonb(row_value)::TEXT, 'sha256'),
          'hex'), '' ORDER BY round_id, submission_id), ''), 'sha256'), 'hex'))
      FROM public.lab_arena_submissions AS row_value
      WHERE NOT ((round_id = v_round_id AND submission_id = v_baseline_id)
        OR (round_id = v_archive_round_id
          AND submission_id = v_archive_submission_id))),
    'runs', (SELECT pg_catalog.jsonb_build_object(
      'count', pg_catalog.count(*), 'sha256', 'sha256:' || pg_catalog.encode(
        extensions.digest(COALESCE(pg_catalog.string_agg(pg_catalog.encode(
          extensions.digest(pg_catalog.to_jsonb(row_value)::TEXT, 'sha256'),
          'hex'), '' ORDER BY run_id), ''), 'sha256'), 'hex'))
      FROM public.lab_arena_runs AS row_value
      WHERE NOT ((round_id = v_round_id AND submission_id = v_baseline_id)
        OR (round_id = v_archive_round_id
          AND submission_id = v_archive_submission_id))),
    'ledger', (SELECT pg_catalog.jsonb_build_object(
      'count', pg_catalog.count(*), 'sha256', 'sha256:' || pg_catalog.encode(
        extensions.digest(COALESCE(pg_catalog.string_agg(pg_catalog.encode(
          extensions.digest(pg_catalog.to_jsonb(row_value)::TEXT, 'sha256'),
          'hex'), '' ORDER BY entry_id), ''), 'sha256'), 'hex'))
      FROM public.lab_arena_ledger AS row_value
      WHERE round_id IN (v_round_id, 'arena-2026-09-19',
                         'arena-2026-09-17-rerun285archive')
        AND NOT ((round_id = v_round_id AND submission_id = v_baseline_id)
        OR (round_id = v_archive_round_id
          AND submission_id = v_archive_submission_id))),
    'weights', (SELECT pg_catalog.jsonb_build_object(
      'count', pg_catalog.count(*), 'sha256', 'sha256:' || pg_catalog.encode(
        extensions.digest(COALESCE(pg_catalog.string_agg(pg_catalog.encode(
          extensions.digest(pg_catalog.to_jsonb(row_value)::TEXT, 'sha256'),
          'hex'), '' ORDER BY network, netuid, epoch), ''), 'sha256'), 'hex'))
      FROM public.lab_arena_accepted_weight_states AS row_value)
  ) INTO v_protected_after;
  v_expected_round := v_terminal_round || pg_catalog.jsonb_build_object(
    'status', 'stage1',
    'status_generation', (v_terminal_round ->> 'status_generation')::BIGINT + 1,
    'stage_generation', (v_terminal_round ->> 'stage_generation')::BIGINT + 1,
    'configuration_doc', v_new_configuration,
    'participants', v_new_participants,
    'stage1_scoring_plan_doc', NULL,
    'stage2_scoring_plan_doc', NULL,
    'stage3_scoring_plan_doc', NULL,
    'finalists', NULL, 'publication_doc', NULL,
    'published_at', NULL, 'cancel_reason', NULL
  );
  v_expected_baseline := v_terminal_baseline || pg_catalog.jsonb_build_object(
    'source_ref', v_source_ref,
    'source_size_bytes', p_source_size_bytes,
    'submission_doc', COALESCE(v_terminal_baseline -> 'submission_doc', '{}'::JSONB) ||
      pg_catalog.jsonb_build_object(
        'source_ref', v_source_ref,
        'source_size_bytes', p_source_size_bytes,
        'source_sha256', p_source_sha256,
        'source_commit', p_source_commit
      )
  );
  IF v_protected_after IS DISTINCT FROM v_protected_before
     OR public.lab_arena_sep18_rerun291_archive_valid295_v1() IS NOT TRUE
     OR (SELECT pg_catalog.to_jsonb(row_value) - 'updated_at'
         FROM public.lab_arena_rounds AS row_value
         WHERE round_id = v_round_id) IS DISTINCT FROM
        (v_expected_round - 'updated_at')
     OR (SELECT pg_catalog.to_jsonb(row_value)
         FROM public.lab_arena_submissions AS row_value
         WHERE round_id = v_round_id AND submission_id = v_baseline_id)
        IS DISTINCT FROM v_expected_baseline
     OR (SELECT pg_catalog.count(*) FROM public.lab_arena_runs
         WHERE round_id = v_round_id AND submission_id = v_baseline_id
           AND kind = 'execute' AND status = 'pending'
           AND output_ref IS NULL AND attempt = 1
           AND assignment_id LIKE '%:rerun295') <> 20
     OR EXISTS (SELECT 1 FROM public.lab_arena_ledger
                WHERE round_id = v_round_id AND submission_id = v_baseline_id)
     OR EXISTS (
       SELECT 1
       FROM pg_catalog.generate_series(0, 19) AS positions(icp_position)
       CROSS JOIN LATERAL (
         SELECT public.lab_arena__successful_icp_cost_state(
           v_round_id, v_baseline_id, positions.icp_position
         ) AS state
       ) AS costs
       WHERE COALESCE((costs.state ->> 'settled_microusd')::BIGINT, -1) <> 0
          OR COALESCE((costs.state ->> 'reserved_or_uncertain_microusd')::BIGINT, -1) <> 0
          OR COALESCE((costs.state ->> 'inflight_calls')::BIGINT, -1) <> 0
          OR COALESCE((costs.state ->> 'success_unresolved_microusd')::BIGINT, -1) <> 0
     )
     OR EXISTS (SELECT 1 FROM public.lab_arena_runs
                WHERE round_id = v_round_id AND submission_id = v_baseline_id
                  AND kind = 'score') THEN
    RAISE EXCEPTION 'Sep18 rerun295 atomic preservation differs'
      USING ERRCODE = '55000';
  END IF;
  RETURN pg_catalog.jsonb_build_object(
    'status', 'prepared', 'round_id', v_round_id,
    'baseline_execute_assignments', 20,
    'archived_runs', 51,
    'archived_ledger_entries', 11025,
    'execute_namespace', 'rerun295',
    'score_namespace', 'score:rerun295',
    'openrouter_calls_per_icp', 200,
    'source_size_bytes', p_source_size_bytes,
    'source_sha256', p_source_sha256,
    'source_commit', p_source_commit
  );
END;
$prepare_sep18_published_rerun295$;
ALTER FUNCTION public.lab_arena_prepare_sep18_published_rerun295_v1(
  BIGINT, TEXT, TEXT, TEXT, JSONB
) OWNER TO lab_arena_owner;
REVOKE ALL ON FUNCTION public.lab_arena_prepare_sep18_published_rerun295_v1(
  BIGINT, TEXT, TEXT, TEXT, JSONB
) FROM PUBLIC, anon, authenticated, service_role, lab_arena_service;
GRANT EXECUTE ON FUNCTION public.lab_arena_prepare_sep18_published_rerun295_v1(
  BIGINT, TEXT, TEXT, TEXT, JSONB
) TO lab_arena_service;

