79970e02a303e6c3b10f5155b3c33b:2:19:1.json", "icp_position": 19, "scored_run_id": "arena-2026-09-18:sub-e079970e02a303e6c3b10f5155b3c33b:2:19:1", "submission_id": "sub-e079970e02a303e6c3b10f5155b3c33b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:10:1.json", "icp_position": 10, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:10:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:11:1.json", "icp_position": 11, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:11:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:12:1.json", "icp_position": 12, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:12:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:13:1.json", "icp_position": 13, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:13:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:14:1.json", "icp_position": 14, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:14:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:15:1.json", "icp_position": 15, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:15:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:16:1.json", "icp_position": 16, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:16:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:17:1.json", "icp_position": 17, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:17:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:18:1.json", "icp_position": 18, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:18:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}, {"output_ref": "arena/arena-2026-09-18/outputs/arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:19:1.json", "icp_position": 19, "scored_run_id": "arena-2026-09-18:sub-e0fc3e14a60953684473c1969f4a9b8b:2:19:1", "submission_id": "sub-e0fc3e14a60953684473c1969f4a9b8b"}], "schema_version": "leadpoet.lab_arena.scoring_plan.v1"}, "stage3_scoring_plan_doc": null, "champion_fallback_providers": []}$terminal_round$::JSONB;
  v_unsettled_cost_count BIGINT;
BEGIN
  IF NEW.round_id = 'arena-2026-09-18'
     AND OLD.status = 'scored' AND NEW.status = 'published'
     AND EXISTS (SELECT 1 FROM public.lab_arena_rounds
                 WHERE round_id = 'arena-2026-09-18-rerun291archive') THEN
    SELECT pg_catalog.count(*) INTO v_unsettled_cost_count
    FROM public.lab_arena_submissions AS submission
    CROSS JOIN (VALUES ('execute'::TEXT), ('score'::TEXT)) AS kinds(kind)
    CROSS JOIN LATERAL (
      SELECT public.lab_arena__successful_call_cost_state(
        submission.submission_id, kinds.kind, NULL
      ) AS state
    ) AS costs
    WHERE submission.round_id = NEW.round_id
      AND (
        COALESCE((costs.state ->> 'inflight_calls')::BIGINT, -1) <> 0
        OR COALESCE((costs.state ->> 'success_unresolved_calls')::BIGINT, -1) <> 0
      );
    IF NEW.reward_basis_hash IS DISTINCT FROM
         v_terminal_round ->> 'reward_basis_hash'
       OR NEW.reward_basis_doc IS DISTINCT FROM
            v_terminal_round -> 'reward_basis_doc'
       OR NEW.signing_key_doc IS DISTINCT FROM
            v_terminal_round -> 'signing_key_doc'
       OR NEW.effective_reward_epoch IS DISTINCT FROM
            (v_terminal_round ->> 'effective_reward_epoch')::BIGINT
       OR NEW.reward_activated_at IS DISTINCT FROM
            (v_terminal_round ->> 'reward_activated_at')::TIMESTAMPTZ
       OR NEW.king_outcome IS DISTINCT FROM
            v_terminal_round ->> 'king_outcome'
       OR NEW.king_hotkey IS DISTINCT FROM
            v_terminal_round ->> 'king_hotkey'
       OR NEW.king_start_epoch IS DISTINCT FROM
            (v_terminal_round ->> 'king_start_epoch')::BIGINT
       OR NEW.promotion_required IS DISTINCT FROM
            (v_terminal_round ->> 'promotion_required')::BOOLEAN
       OR NEW.promotion_doc IS DISTINCT FROM
            NULLIF(v_terminal_round -> 'promotion_doc', 'null'::JSONB)
       OR NEW.baseline_promoted_at IS DISTINCT FROM
            (v_terminal_round ->> 'baseline_promoted_at')::TIMESTAMPTZ
       OR NEW.champion_funding_frozen IS DISTINCT FROM
            (v_terminal_round ->> 'champion_funding_frozen')::BOOLEAN
       OR NEW.champion_submission_id IS DISTINCT FROM
            v_terminal_round ->> 'champion_submission_id'
       OR NEW.champion_hotkey IS DISTINCT FROM
            v_terminal_round ->> 'champion_hotkey'
       OR NEW.champion_fallback_providers IS DISTINCT FROM
            ARRAY(SELECT pg_catalog.jsonb_array_elements_text(
              COALESCE(v_terminal_round -> 'champion_fallback_providers', '[]'::JSONB)
            ))
       OR NEW.publication_doc #>> '{king_decision,outcome}' IS DISTINCT FROM
            v_terminal_round #>> '{publication_doc,king_decision,outcome}'
       OR NEW.publication_doc #>> '{king_decision,king_submission_id}' IS DISTINCT FROM
            v_terminal_round #>> '{publication_doc,king_decision,king_submission_id}'
       OR NEW.publication_doc #>> '{king_decision,king_hotkey}' IS DISTINCT FROM
            v_terminal_round #>> '{publication_doc,king_decision,king_hotkey}'
       OR NEW.publication_doc #>> '{king_decision,winner_submission_id}' IS DISTINCT FROM
            v_terminal_round #>> '{publication_doc,king_decision,winner_submission_id}'
       OR NEW.configuration_doc ->> 'baseline_source_url' IS DISTINCT FROM
            'https://github.com/leadpoet/leadpoet-sales-agent/archive/refs/heads/lab.tar.gz'
       OR (NEW.configuration_doc - 'schedule' - 'baseline_source_url')
            IS DISTINCT FROM
            ((v_terminal_round -> 'configuration_doc') - 'schedule' -
             'baseline_source_url')
       OR public.lab_arena_sep18_rerun291_archive_valid295_v1() IS NOT TRUE
       OR (SELECT pg_catalog.count(DISTINCT assignment_id)
           FROM public.lab_arena_runs
           WHERE round_id = NEW.round_id
             AND submission_id = 'baseline-2026-09-18'
             AND kind = 'execute' AND assignment_id LIKE '%:rerun295') <> 20
       OR (SELECT pg_catalog.count(DISTINCT icp_position)
           FROM public.lab_arena_runs
           WHERE round_id = NEW.round_id
             AND submission_id = 'baseline-2026-09-18'
             AND kind = 'execute' AND assignment_id LIKE '%:rerun295'
             AND per_icp_score IS NOT NULL) <> 20
       OR EXISTS (
         SELECT 1 FROM public.lab_arena_runs
         WHERE round_id = NEW.round_id
           AND submission_id = 'baseline-2026-09-18'
           AND kind = 'score'
           AND assignment_id NOT LIKE '%:score:rerun295'
       )
       OR EXISTS (
         SELECT 1 FROM public.lab_arena_runs AS executed
         WHERE executed.round_id = NEW.round_id
           AND executed.submission_id = 'baseline-2026-09-18'
           AND executed.kind = 'execute'
           AND executed.assignment_id LIKE '%:rerun295'
           AND executed.status = 'accepted'
           AND NOT EXISTS (
             SELECT 1 FROM public.lab_arena_runs AS judged
             WHERE judged.round_id = executed.round_id
               AND judged.submission_id = executed.submission_id
               AND judged.kind = 'score' AND judged.status = 'accepted'
               AND judged.scored_run_id = executed.run_id
               AND judged.assignment_id LIKE '%:score:rerun295'
           )
       )
       OR EXISTS (SELECT 1 FROM public.lab_arena_runs
                  WHERE round_id = NEW.round_id
                    AND status IN ('pending', 'leased', 'submitted'))
       OR v_unsettled_cost_count <> 0
       THEN
      RAISE EXCEPTION 'Sep18 rerun295 publication conflicts with sealed reward, winner, source, cost, or completion state'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  RETURN NEW;
END;
$sep18_published_rerun295_publication_guard$;
ALTER FUNCTION public.lab_arena_sep18_published_rerun295_publication_guard_v1()
  OWNER TO lab_arena_owner;
REVOKE ALL ON FUNCTION public.lab_arena_sep18_published_rerun295_publication_guard_v1()
  FROM PUBLIC, anon, authenticated, service_role, lab_arena_service;
DROP TRIGGER IF EXISTS lab_arena_sep18_published_rerun295_publication_guard
  ON public.lab_arena_rounds;
CREATE TRIGGER lab_arena_sep18_published_rerun295_publication_guard
  BEFORE UPDATE ON public.lab_arena_rounds
  FOR EACH ROW
  EXECUTE FUNCTION public.lab_arena_sep18_published_rerun295_publication_guard_v1();

REVOKE CREATE ON SCHEMA public FROM lab_arena_owner;
NOTIFY pgrst, 'reload schema';
COMMIT;
